def admit_bootstrap_main_program(source, legacy_declaration):
    tree = ast.parse(source)
    if ast.dump(tree, include_attributes=False) != EXPECTED_MODULE_AST:
        raise ValueError('bootstrap Session differs from its complete admitted module AST')
    program = copy.deepcopy(next((node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == 'bootstrap_main_program')))
    program.name = 'start_game_main_loop_frame_fields'
    program.returns = ast.parse('def f() -> FirstDeploymentFrame: pass').body[0].returns
    program.body = program.body[1:]
    changed_call = 0
    for node in ast.walk(program):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.YieldFrom):
            call = node.value.value
            if isinstance(call, ast.Call) and isinstance(call.func, ast.Name) and (call.func.id == '_bootstrap_dispatch_call_steps'):
                call.func.id = 'display_call_fields'
                node.value = call
                changed_call += 1
    if changed_call != 1:
        raise ValueError('exactly one original indexed scene call must reverse')
    changed = 0
    expected_yield = ast.dump(ast.parse('frame = yield BootstrapMainWait(state, frame).validate()').body[0], include_attributes=False)
    for node in ast.walk(program):
        if isinstance(node, ast.While):
            for index, statement in enumerate(node.body):
                if ast.dump(statement, include_attributes=False) == expected_yield:
                    node.body[index] = ast.parse("state.progress('original3BC main scene request wait')").body[0]
                    changed += 1
    original = ast.parse('def start_game_main_loop_frame_fields(' + legacy_declaration['signature'] + ') -> ' + legacy_declaration['returns'] + ':\n' + '\n'.join(('    ' + line for line in legacy_declaration['flow'].splitlines()))).body[0]
    if changed != 1 or ast.dump(program, include_attributes=False) != ast.dump(original, include_attributes=False):
        raise ValueError('bootstrap Session does not reverse to the complete original owner')
    from pathlib import Path
    from .compiler_force_turn_steps import admit_force_turn_program
    directory = Path(__file__).resolve().parent
    admit_force_turn_program((directory / 'force_turn_steps.py').read_text(encoding='utf-8'), {'business_main': (directory / 'business_main.py').read_text(encoding='utf-8'), 'business_commands': (directory / 'business_commands.py').read_text(encoding='utf-8'), 'high_level_gameplay_flow.business_services': (directory.parent / 'high_level_gameplay_flow/business_services.py').read_text(encoding='utf-8')})
    return dict(whole_original_owner=768, wait=956, complete_module_AST=True, complete_original_algorithm_restored=True, native_lowerer_changed=False, new_formal_bytes=0)
